Here is the commit message:
xfs: fix a UAF problem in xattr repair

The xchk_setup_xattr_buf function can allocate a new value buffer, which
means that any reference to ab->value before the call could become a
dangling pointer.  Fix this by moving an assignment to after the buffer
setup.

Cc: stable@vger.kernel.org # v6.10
Fixes: e47dcf113ae348 ("xfs: repair extended attributes")
Signed-off-by: Darrick J. Wong <djwong@kernel.org>
Reviewed-by: Christoph Hellwig <hch@lst.de>
Signed-off-by: Carlos Maiolino <cem@kernel.org>

Here is the root cause:
The variable `args.value` was initialized to `ab->value` before the call to `xchk_setup_xattr_buf`, which can reallocate `ab->value`, leaving `args.value` as a dangling pointer and causing a use-after-free.

Here is the patch:
  */
 STATIC int
 xrep_xattr_salvage_remote_attr(
 	struct xrep_xattr		*rx,
 	struct xfs_attr_leaf_entry	*ent,
 	unsigned int			nameidx,
 	const char			*buf_end,
 	struct xfs_attr_leaf_name_remote *rentry,
 	unsigned int			ent_idx,
 	struct xfs_buf			*leaf_bp)
 {
 	struct xchk_xattr_buf		*ab = rx->sc->buf;
 	struct xfs_da_args		args = {
 		.trans			= rx->sc->tp,
 		.dp			= rx->sc->ip,
 		.index			= ent_idx,
 		.geo			= rx->sc->mp->m_attr_geo,
 		.owner			= rx->sc->ip->i_ino,
 		.attr_filter		= ent->flags & XFS_ATTR_NSP_ONDISK_MASK,
 		.namelen		= rentry->namelen,
 		.name			= rentry->name,
-		.value			= ab->value,
 		.valuelen		= be32_to_cpu(rentry->valuelen),
 	};
 	unsigned int			namesize;
 	int				error;

 	/*
 	 * Decode the leaf remote entry format.  If something seems wrong, we
 	 * junk the attribute.  Note that we should never find a zero-length
 	 * remote attribute value.
 	 */
 	namesize = xfs_attr_leaf_entsize_remote(rentry->namelen);
 	if ((char *)rentry + namesize > buf_end)
 		return 0;
 	if (args.valuelen == 0 ||
 	    !xrep_xattr_want_salvage(rx, ent->flags, rentry->name,
 			rentry->namelen, NULL, args.valuelen))
 		return 0;
 	if (!xchk_xattr_set_map(rx->sc, ab->usedmap, nameidx, namesize))
 		return 0;

 	/*
 	 * Enlarge the buffer (if needed) to hold the value that we're trying
 	 * to salvage from the old extended attribute data.
 	 */
 	error = xchk_setup_xattr_buf(rx->sc, args.valuelen);
 	if (error == -ENOMEM)
 		error = -EDEADLOCK;
 	if (error)
 		return error;
+	args.value = ab->value;

 	/* Look up the remote value and stash it for reconstruction. */
 	error = xfs_attr3_leaf_getvalue(leaf_bp, &args);
 	if (error || args.rmtblkno == 0)
 		goto err_free;

 	error = xfs_attr_rmtval_get(&args);
 	if (error)
 		goto err_free;

 	/* Try to save this attribute. */
 	error = xrep_xattr_salvage_key(rx, ent->flags, rentry->name,
 			rentry->namelen, ab->value, args.valuelen);
 err_free:
 	/* remote value was garbage, junk it */
 	if (error == -EFSBADCRC || error == -EFSCORRUPTED)
 		error = 0;
 	return error;
 }



